126	__aicore__ inline void FlashAttentionScoreEnhanceDropMaskAdapter::CopyIn(int64_t offset, int32_t calSize)
127	{
128	    AscendC::LocalTensor<uint8_t> dropMaskUb = dropMaskInputQueue.template AllocTensor<uint8_t>();
129	    AscendC::DataCopyParams dataCopyParams;
130	    dataCopyParams.blockCount = 1;
131	    dataCopyParams.dstStride = 0;
132	    dataCopyParams.blockLen = CeilDiv(calSize, AscendC::ONE_BYTE_BIT_SIZE);
133	    dataCopyParams.srcStride = 0;
134	    AscendC::DataCopyPadParams dataCopyPadParams;
135	    DataCopyPad(dropMaskUb, dropMaskGm[offset >> 3], dataCopyParams, dataCopyPadParams); // 右移3位表示除8
136	
137	    dropMaskInputQueue.EnQue(dropMaskUb);
138	}
139	
140	__aicore__ inline void FlashAttentionScoreEnhanceDropMaskAdapter::Compute(
141	    int32_t calSize, AscendC::LocalTensor<half> &dropMaskSelSrc, const AscendC::BinaryRepeatParams &binaryRepeatParams)
142	{
143	    AscendC::LocalTensor<half> dropMaskSelRes = dropMaskSelResTBuf.template Get<half>();
144	    AscendC::LocalTensor<uint8_t> dropMaskUb = dropMaskInputQueue.template DeQue<uint8_t>();
145	    AscendC::PipeBarrier<PIPE_V>();
146	
147	    int32_t loop = calSize / SELECT_MAX_REPEAT_MASK;
148	    for (int32_t idx = 0; idx < loop; ++idx) {
149	        Select(dropMaskSelRes[SELECT_MAX_MASK * idx],
150	               dropMaskUb[SELECT_MAX_SRC_STRIDE * idx],
151	               dropMaskSelSrc,
152	               static_cast<half>(0),
153	               AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE,
154	               SELECT_MAX_MASK,
155	               SELECT_MAX_REPEAT,
156	               binaryRepeatParams);
157	    }
158	
159	    int32_t repeat = CeilDiv(calSize, SELECT_MAX_MASK) - SELECT_MAX_REPEAT * loop;
160	    Select(dropMaskSelRes[SELECT_MAX_MASK * loop],
161	           dropMaskUb[SELECT_MAX_SRC_STRIDE * loop],
162	           dropMaskSelSrc,
163	           static_cast<half>(0),
164	           AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE,
165	           Min(calSize, SELECT_MAX_MASK),
166	           repeat,
167	           binaryRepeatParams);
168	
169	    AscendC::PipeBarrier<PIPE_V>();
170	    dropMaskInputQueue.FreeTensor(dropMaskUb);
171	
172	    AscendC::LocalTensor<uint8_t> dropMaskOutUb = dropMaskOutputQueue.template AllocTensor<uint8_t>();
173	    Cast(dropMaskOutUb, dropMaskSelRes, AscendC::RoundMode::CAST_NONE, calSize);
174	    dropMaskOutputQueue.EnQue(dropMaskOutUb);
175	}
176	
177	__aicore__ inline void FlashAttentionScoreEnhanceDropMaskAdapter::CopyOut(int64_t offset, int32_t calSize)
178	{
179	    AscendC::LocalTensor<uint8_t> dropMaskOutUb = dropMaskOutputQueue.template DeQue<uint8_t>();
180	    AscendC::PipeBarrier<PIPE_V>();
181	    AscendC::DataCopyParams dataCopyParams;
182	    dataCopyParams.blockCount = 1;
183	    dataCopyParams.blockLen = calSize;
184	    dataCopyParams.dstStride = 0;
185	    dataCopyParams.srcStride = 0;
186	    DataCopyPad(outputGm[offset], dropMaskOutUb, dataCopyParams);
187	    dropMaskOutputQueue.FreeTensor(dropMaskOutUb);
188	}
189	
190	__aicore__ inline void FlashAttentionScoreEnhanceDropMaskAdapter::SyncAllCores()
191	{
192	    AscendC::SyncAll();
193	}
194	
195	#endif // FLASH_ATTENTION_SCORE_ENHANCE_DROP_MASK_ADAPTER_H
